// 4 digital channel pins on Arduino Uno: 2, 3, 4, 5
const int NUM_CHANNELS = 4;
int sensorPins[NUM_CHANNELS] = {2, 3, 4, 5};

void setup() {
 Serial.begin(115200);
 for (int i = 0; i < NUM_CHANNELS; i++) pinMode(sensorPins[i], INPUT);
}

void loop() {
 for (int i = 0; i < NUM_CHANNELS; i++) {
 Serial.print(digitalRead(sensorPins[i])); // typically LOW = line detected (black surface)
 Serial.print(" ");
 }
 Serial.println();
 delay(100);
}",

